{
  "findings": [
    {
      "check_id": "CKV_AZURE_221",
      "title": "Function App public network access is enabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The Function App does not disable public network access, allowing it to be reached through its public endpoint."
    },
    {
      "check_id": "CKV_AZURE_67",
      "title": "Function App does not enable the latest HTTP version",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The site configuration does not enable HTTP/2, so the Function App may use the older HTTP/1.1 protocol."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Function App authentication is not enabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The Function App has no authentication configuration, allowing requests to reach the application without platform-enforced authentication."
    }
  ],
  "patched_code": "resource "azurerm_linux_function_app" "alert_function" {
  name                          = "smart-manufacturing-iot-monitoring-platform-function-app-alerts"
  resource_group_name           = azurerm_resource_group.smart_manufacturing.name
  location                      = azurerm_resource_group.smart_manufacturing.location
  service_plan_id               = azurerm_service_plan.dashboard_plan.id
  storage_account_name          = azurerm_storage_account.function_storage.name
  storage_account_access_key    = azurerm_storage_account.function_storage.primary_access_key
  public_network_access_enabled = false

  site_config {
    http2_enabled = true

    application_stack {
      node_version = "18"
    }
  }

  auth_settings_v2 {
    auth_enabled           = true
    require_authentication = true
    unauthenticated_action = "Return401"
  }

  app_settings = {
    "FUNCTIONS_WORKER_RUNTIME" = "node"
  }
}
",
  "fix_summary": "Disabled public network access, enabled HTTP/2, and configured built-in authentication to reject unauthenticated requests."
}
